package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The quick-add bar: a DRAFT claim of an amount, dated the sheet's entry date while set (else its today) with an empty note, for the
 * person of a name, who is first added with grade A when the name is not on the sheet. It is one
 * change: when the claim is refused the person added for it is not kept, and nothing is recorded.
 */
@Service
public class QuickAddService {

    /** The grade a person added by the quick-add bar is given. */
    static final String GRADE = "A";

    /** What a quick-add made: the claim, for its person, and whether that person was added for it. */
    public record Added(Person person, boolean personAdded, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person existing = people.findBySheetIdAndName(sheetId, name).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, GRADE, null, null);
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null);
        return new Added(person, existing == null, claim);
    }
}
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of name,amount,date,note.");
        }
        if (lines.size() > LINES_MAX) {
            throw refused("Paste at most " + LINES_MAX + " lines at once.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null, line.ref()));
        }
        return added;
    }

    private Line line(String sheetId, int number, String text) {
        String[] fields = text.split(",", 4);
        if (fields.length < 2) {
            throw refused("Line " + number + " needs at least a name and an amount.");
        }
        String name = fields[0].trim();
        if (name.isEmpty()) {
            throw refused("Line " + number + " has no name.");
        }
        Person person = people.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> refused("Line " + number + ": " + name + " is not on this sheet."));
        String amount = fields[1].trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused("Line " + number + ": the amount must have up to two decimals.");
        }
        LocalDate date = null;
        String dated = fields.length > 2 ? fields[2].trim() : "";
        if (!dated.isEmpty()) {
            try {
                date = LocalDate.parse(dated);
            } catch (DateTimeParseException e) {
                throw refused("Line " + number + ": the date must be YYYY-MM-DD.");
            }
        }
        String note = fields.length > 3 ? fields[3].trim() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0 && ClaimService.reference(note.substring(hash + 2)) != null) {
            ref = ClaimService.reference(note.substring(hash + 2));
            note = note.substring(0, hash).trim();
        }
        if (ref != null && ref.length() > REF_MAX) {
            throw refused("Line " + number + ": the reference is longer than " + REF_MAX + " characters.");
        }
        if (note.length() > NOTE_MAX) {
            throw refused("Line " + number + ": the note is longer than " + NOTE_MAX + " characters.");
        }
        return new Line(person, new BigDecimal(amount), date, note, ref);
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
    }

    /**
     * The rates of the sheet's ancestors, nearest first, up to {@link Dues#PARENT_LEVELS}, each as it
     * stood at the end of a date (null: as it stands): an ancestor's rates as kept for the last snapshot
     * on or before that date when it is before the ancestor's today (none when nothing was kept by
     * then), else as they stand. The parent itself is not dated: the chain is the one set now.
     */
    @Transactional(readOnly = true)
    public List<List<Rate>> inherited(String sheetId, LocalDate day) {
        return sheets.ancestors(sheetId).stream().limit(Dues.PARENT_LEVELS)
                .map(ancestor -> past(ancestor, day) ? keptRates(ancestor, day)
                        : rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(ancestor))
                .toList();
    }

    /** A sheet's rates as kept for the last snapshot on or before a date; none when nothing was kept by then. */
    private List<Rate> keptRates(String sheetId, LocalDate day) {
        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByIdDesc(sheetId, day)
                .map(snapshot -> rates(sheetId, json.readValue(snapshot.getState(), State.class)))
                .orElse(List.of());
    }

    private static AsOf restored(Sheet now, LocalDate day, State state, List<List<Rate>> inherited) {
        Sheet sheet = now.asOf(day,
                state.settings().stream().map(s -> new DatedSetting(s.key(), s.from(), s.value())).toList(),
                state.policyDate());
        List<Rate> rates = rates(now.getId(), state);
        Map<Long, Person> people = new LinkedHashMap<>();
        for (PersonState p : state.people()) {
            Person person = new Person(now.getId(), p.name(), p.grade(), p.terms(), p.contact());
            p.grades().forEach(g -> person.gradeFrom(g.grade(), g.from()));
            p.holds().forEach(h -> person.hold(h.from(), h.to()));
            if (p.aliases() != null) {
                p.aliases().forEach(person::addAlias);
            }
            if (p.retiredFrom() != null) {
                person.retire(p.retiredFrom());
            }
            people.put(p.id(), person);
        }
        Map<Long, Claim> claims = new LinkedHashMap<>();
        for (ClaimState c : state.claims()) {
            Claim claim = new Claim(now.getId(), c.personId(), c.amount(), c.date(), 0, c.dueBy(), "", c.corrects());
            claim.become(c.status());
            claim.number(c.number());
            claim.settleDue(c.settledDue());
            if (c.stated()) {
                claim.bind(c.statedDue());
            }
            claim.defer(c.deferredUntil());
            claims.put(c.id(), claim);
        }
        Dues.Basis basis = new Dues.Basis(sheet, rates, inherited, correction -> claims.values().stream()
                .filter(c -> Objects.equals(c.getPersonId(), correction.getPersonId())
                        && Objects.equals(c.getNumber(), correction.getCorrects()))
                .findFirst());
        return new AsOf(sheet, people, claims, basis);
    }

    /** The rates kept in a sheet's state, held in no store. */
    private static List<Rate> rates(String sheetId, State state) {
        return state.rates().stream().map(r -> {
            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.pct());
            rate.setToDate(r.to());
            return rate;
        }).toList();
    }

    private static PersonState kept(Person p) {
        return new PersonState(p.getId(), p.getName(), p.getGrade(),
                p.getGradesFrom().entrySet().stream().map(e -> new GradeState(e.getKey(), e.getValue())).toList(),
                p.getTerms(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
                p.getRetiredFrom(), p.getContact(), p.getAliases());
    }

    private static ClaimState kept(Claim c) {
        return new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(), c.getDueBy(), c.getStatus(),
                c.getNumber(), c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getCorrects(), c.getDeferredUntil());
    }
}

